    protected void preloadLines(TransDate _date)
    {
        // Data type = GUPPriceEngineMarginCodeLine.
        this.lineList = this.loadAllAvailableLines(_date);

        this.loadLineExclusions(lineList, _date);

        // Key = Datasource name (table name or provider class name). Value = GUPPriceEngineDatasourceAggregationObject
        Map pricingAttributeDatasourceMapTemp = new Map(Types::String, Types::AnyType);

        ListEnumerator enumerator = lineList.getEnumerator();
        while (enumerator.moveNext())
        {
            GUPPriceEngineMarginCodeLine line = enumerator.current();

            this.loadLineRequiredFields(line, line.parmHeaderAttribute(), pricingAttributeDatasourceMapTemp);
            
            this.loadLineRequiredFields(line, line.parmLineAttribute(), pricingAttributeDatasourceMapTemp);
        }

        this.pricingAttributeDatasourceMap = pricingAttributeDatasourceMapTemp;
    }

    private List loadAllAvailableLines(TransDate _date)
    {
        // List of GUPPriceEngineMarginComponent.
        List lineListTemp = new List(Types::AnyType);

        // Temp data for [current] records.
        int64 marginComponentCode;
        GUPPriceMarginComponentSetup setupData;
        GUPMarginComponentPriceAdjustment headerData;
        GUPPriceEngineAttributeGroupObject headerAttributeGroupData;

        GUPPriceMarginComponentSetup marginComponentSetup;
        GUPMarginComponentPriceAdjustment marginComponentHeader;
        GUPMarginComponentPriceAdjustmentLine marginComponentLine;
        GUPPriceComponentCodePriceAttributeGroupCombination groupCombination;
        GUPPricingRule gupPricingRuleHeader, gupPricingRuleLine;
        GUPPricingAttributeGroup gupPricingAttributeGroupHeader, gupPricingAttributeGroupLine;
        UnitOfMeasure unitOfMeasure;

        while select marginComponentSetup
            order by marginComponentSetup.CalculationSequence asc
            join marginComponentHeader
                where marginComponentSetup.PriceComponentCode == marginComponentHeader.MarginComponentCode &&
                    marginComponentHeader.Status == RetailDisabledEnabled::Enabled &&
                    (dateNull() == marginComponentHeader.ValidFrom || marginComponentHeader.ValidFrom <= _date) &&
                    (dateNull() == marginComponentHeader.ValidTo || marginComponentHeader.ValidTo >= _date)
            join marginComponentLine
                where marginComponentHeader.OfferId == marginComponentLine.OfferId
            outer join unitOfMeasure
                where unitOfMeasure.RecId == marginComponentLine.UnitOfMeasure 
            join groupCombination
                where marginComponentLine.PriceAttributeGroupCombinationRecId == groupCombination.RecId
            outer join gupPricingRuleHeader
                where marginComponentHeader.HeaderPricingRule == gupPricingRuleHeader.RecId
            outer join gupPricingRuleLine
                where marginComponentLine.LinePricingRule == gupPricingRuleLine.RecId
            outer join gupPricingAttributeGroupHeader
                where gupPricingRuleHeader.PriceAttributeGroup == gupPricingAttributeGroupHeader.RecId
            outer join gupPricingAttributeGroupLine
                where gupPricingRuleLine.PriceAttributeGroup == gupPricingAttributeGroupLine.RecId
        {
            // Found new margin component.
            if (!marginComponentCode || marginComponentCode != marginComponentSetup.PriceComponentCode)
            {
                setupData = marginComponentSetup.data();
                marginComponentCode = marginComponentSetup.PriceComponentCode;
            }

            // Same header may applies to many lines.
            if (!headerData || headerData.RecId != marginComponentHeader.RecId)
            {
                headerData = marginComponentHeader.data();
                headerAttributeGroupData = this.createAttributeGroupObject(gupPricingRuleHeader, gupPricingAttributeGroupHeader);
            }

            GUPPriceEngineAttributeGroupObject lineAttributeGroup = 
                this.createAttributeGroupObject(gupPricingRuleLine, gupPricingAttributeGroupLine);

            GUPPriceEngineMarginCodeLine marginCodeLine = new GUPPriceEngineMarginCodeLine(
                setupData,
                headerData,
                marginComponentLine.data(),
                headerAttributeGroupData,
                lineAttributeGroup, 
                unitOfMeasure);

            lineListTemp.addEnd(marginCodeLine);

        }
            
        return lineListTemp;
    }

    /// <summary>
    /// Assign the exclusion data to each attribute group's header and line.
    /// </summary>
    /// <param name = "_lineList">Current margin code lines.</param>
    /// <param name = "_date">Date of the cache.</param>
    public void loadLineExclusions(List _lineList, TransDate _date)
    {
        // Key = GUPPricingRule.RecId (An unique header/line record for each TA line).
        // Value = GUPPriceEngineAttributeGroupObject
        Map pricingRuleIdMap = new Map(Types::Int64, Types::AnyType);
        
        ListEnumerator enumerator = _lineList.getEnumerator();
        while (enumerator.moveNext())
        {
            GUPPriceEngineMarginCodeLine line = enumerator.current();

            // Multiple lines may have reference to the same header group. This is an expected behavior. 
            if(line.parmHeaderAttribute() != null)
            {
                GUPPricingRule pricingRule = line.parmHeaderAttribute().parmPricingRule();
                pricingRuleIdMap.add(pricingRule.recId, line.parmHeaderAttribute());
            }

            if(line.parmLineAttribute() != null)
            {
                GUPPricingRule pricingRule = line.parmLineAttribute().parmPricingRule();
                pricingRuleIdMap.add(pricingRule.recId, line.parmLineAttribute());
            }
        }

        GUPPriceMarginComponentSetup marginComponentSetup;
        GUPMarginComponentPriceAdjustment marginComponentHeader;
        GUPMarginComponentPriceAdjustmentLine marginComponentLine;
        GUPPricingAttributeLineState lineExclusion;
        CustTable custTable;
        InventTable inventTable;

        // CustTable exclusion.
        while select marginComponentSetup
            order by marginComponentSetup.CalculationSequence asc
            join HeaderPricingRule from marginComponentHeader
                where marginComponentSetup.PriceComponentCode == marginComponentHeader.MarginComponentCode &&
                    marginComponentHeader.Status == RetailDisabledEnabled::Enabled &&
                    (dateNull() == marginComponentHeader.ValidFrom || marginComponentHeader.ValidFrom <= _date) &&
                    (dateNull() == marginComponentHeader.ValidTo || marginComponentHeader.ValidTo >= _date)
            exists join lineExclusion
                where lineExclusion.LineType == GUPPricingAttributeLineType::Exclude
                    && lineExclusion.ParentTableId == tableNum(GUPPricingRule)
                    && lineExclusion.LineTableId == tableNum(InventTable)
                    && lineExclusion.ParentRecId == marginComponentHeader.HeaderPricingRule
            join AccountNum from custTable
                where custTable.RecId == lineExclusion.LineRecId
        {
            GUPPriceEngineAttributeGroupObject attributeGroup = pricingRuleIdMap.lookup(marginComponentHeader.HeaderPricingRule);
            // Refer to CustTable.AccountNum, as salesTable stores custAccount instead of custTable.recId
            attributeGroup.addExcludedId(custTable.AccountNum);
        }

        // InventTable exclusion.
        while select marginComponentSetup
            order by marginComponentSetup.CalculationSequence asc
            exists join marginComponentHeader
                where marginComponentSetup.PriceComponentCode == marginComponentHeader.MarginComponentCode &&
                    marginComponentHeader.Status == RetailDisabledEnabled::Enabled &&
                    (dateNull() == marginComponentHeader.ValidFrom || marginComponentHeader.ValidFrom <= _date) &&
                    (dateNull() == marginComponentHeader.ValidTo || marginComponentHeader.ValidTo >= _date)
            join LinePricingRule from marginComponentLine
                where marginComponentHeader.OfferId == marginComponentLine.OfferId
            exists join lineExclusion
                where lineExclusion.LineType == GUPPricingAttributeLineType::Exclude
                    && lineExclusion.ParentTableId == tableNum(GUPPricingRule)
                    && lineExclusion.LineTableId == tableNum(InventTable)
                    && lineExclusion.ParentRecId == marginComponentLine.LinePricingRule
            join ItemId from inventTable
                where inventTable.RecId == lineExclusion.LineRecId
        {
            GUPPriceEngineAttributeGroupObject attributeGroup = pricingRuleIdMap.lookup(marginComponentLine.LinePricingRule);
            // Refer to InventTable.ItemId, as salesLine stores ItemId instead of recId.
            attributeGroup.addExcludedId(inventTable.ItemId);
        }
    }
